import json

def render(rows, block=False):
    escapes = {"\\": "\\\\", "|": "\\|", "\n": "\\n"}
    def encode(field):
        if block and "\n" in field:
            return '"' + field.replace('"', '""') + '"'
        return "".join(escapes.get(ch, ch) for ch in field)
    return "".join("|".join(encode(field) for field in row) + "\n" for row in rows)

job = {"rows": [["rack|7", "C:\\lot\\new", "S\nT"], ['"one"\n|two\\', "C:\\new", ""], ["plain", "|"]], "block": True}
edge = {"rows": [["a|b", "\n"]], "block": True}
print(json.dumps({"result": render(**job), "edge": {"job": edge, "expected": render(**edge)}}, ensure_ascii=False))

